fn length_of_longest_substring(s: &str) -> usize {
    use std::collections::HashMap;
    let mut last = HashMap::new();
    let mut start = 0;
    let mut best = 0;
    for (i, c) in s.chars().enumerate() {
        if let Some(&index) = last.get(&c) {
            if index >= start {
                start = index + 1;
            }
        }
        last.insert(c, i);
        best = best.max(i - start + 1);
    }
    best
}

