def my_sqrt(x):
    if x < 2:
        return x
    lo, hi = 1, x // 2
    answer = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid <= x:
            answer = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return answer

