fn add_binary(a: &str, b: &str) -> String {
    let (mut i, mut j) = (a.len() as i32 - 1, b.len() as i32 - 1);
    let (a, b) = (a.as_bytes(), b.as_bytes());
    let mut carry = 0;
    let mut result = Vec::new();
    while i >= 0 || j >= 0 || carry > 0 {
        let mut total = carry;
        if i >= 0 {
            total += (a[i as usize] - b'0') as i32;
            i -= 1;
        }
        if j >= 0 {
            total += (b[j as usize] - b'0') as i32;
            j -= 1;
        }
        result.push((b'0' + (total % 2) as u8) as char);
        carry = total / 2;
    }
    result.iter().rev().collect()
}

