bool word_pattern(const std::string& pattern, const std::string& s) {
    std::istringstream stream(s);
    std::vector<std::string> words;
    std::string word;
    while (stream >> word) words.push_back(word);
    if (pattern.size() != words.size()) return false;
    std::unordered_map<char, std::string> forward;
    std::unordered_map<std::string, char> backward;
    for (int i = 0; i < (int)words.size(); i++) {
        char c = pattern[i];
        if (forward.count(c) && forward[c] != words[i]) return false;
        if (backward.count(words[i]) && backward[words[i]] != c) return false;
        forward[c] = words[i];
        backward[words[i]] = c;
    }
    return true;
}

